CREATE TABLE public.plans (id text PRIMARY KEY, name text NOT NULL, broker_limit integer NOT NULL CHECK(broker_limit > 0), monthly_price_cents integer NOT NULL CHECK(monthly_price_cents >= 0), currency text NOT NULL DEFAULT 'BRL', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.plans TO authenticated; GRANT ALL ON public.plans TO service_role;
ALTER TABLE public.plans ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_read ON public.plans FOR SELECT TO authenticated USING(true);
INSERT INTO public.plans(id,name,broker_limit,monthly_price_cents) SELECT * FROM (VALUES ('team15','Equipe 15',15,99900),('team30','Equipe 30',30,179900),('team60','Equipe 60',60,299900),('team100','Equipe 100',100,449900)) AS catalog(id,name,broker_limit,monthly_price_cents);
CREATE TABLE public.profiles (id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, full_name text NOT NULL DEFAULT '', avatar_url text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, UPDATE(full_name,avatar_url) ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.user_roles (user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE, role text NOT NULL CHECK(role='superadmin'), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_global_role ON public.user_roles FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE TABLE public.organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL CHECK(length(trim(name)) BETWEEN 2 AND 160), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.organizations TO authenticated; GRANT ALL ON public.organizations TO service_role;
ALTER TABLE public.organizations ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL UNIQUE REFERENCES public.organizations(id), plan_id text NOT NULL REFERENCES public.plans(id), status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.subscriptions TO authenticated; GRANT ALL ON public.subscriptions TO service_role;
ALTER TABLE public.subscriptions ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.memberships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), user_id uuid NOT NULL, status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','inactive')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(organization_id,user_id));
GRANT SELECT ON public.memberships TO authenticated; GRANT ALL ON public.memberships TO service_role;
ALTER TABLE public.memberships ENABLE ROW LEVEL SECURITY;
CREATE INDEX memberships_user_idx ON public.memberships(user_id, status);
CREATE TABLE public.membership_roles (membership_id uuid NOT NULL REFERENCES public.memberships(id) ON DELETE CASCADE, role text NOT NULL CHECK(role IN ('admin','broker')), PRIMARY KEY(membership_id,role));
GRANT SELECT ON public.membership_roles TO authenticated; GRANT ALL ON public.membership_roles TO service_role;
ALTER TABLE public.membership_roles ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.invitations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid NOT NULL REFERENCES public.organizations(id), email text NOT NULL CHECK(email=lower(trim(email)) AND position('@' IN email)>1), roles text[] NOT NULL CHECK(cardinality(roles)>0 AND roles <@ ARRAY['admin','broker']::text[]), token_hash text NOT NULL UNIQUE CHECK(length(token_hash)=64), status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','revoked')), expires_at timestamptz NOT NULL, created_by uuid NOT NULL, accepted_by uuid, accepted_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT(id,organization_id,email,roles,status,expires_at,created_by,accepted_by,accepted_at,revoked_at,created_at,updated_at) ON public.invitations TO authenticated; GRANT ALL ON public.invitations TO service_role;
ALTER TABLE public.invitations ENABLE ROW LEVEL SECURITY;
CREATE INDEX invitation_capacity_idx ON public.invitations(organization_id,status,expires_at);
CREATE TABLE public.audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), organization_id uuid REFERENCES public.organizations(id), actor_id uuid NOT NULL, action text NOT NULL, target_id uuid, details jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.audit_logs TO authenticated; GRANT ALL ON public.audit_logs TO service_role;
ALTER TABLE public.audit_logs ENABLE ROW LEVEL SECURITY;
CREATE INDEX audit_org_time_idx ON public.audit_logs(organization_id,created_at DESC);
CREATE FUNCTION public.is_superadmin() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='superadmin') $$;
CREATE FUNCTION public.org_member(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.memberships m JOIN public.organizations o ON o.id=m.organization_id WHERE m.organization_id=org AND m.user_id=auth.uid() AND m.status='active' AND o.status='active') $$;
CREATE FUNCTION public.org_admin(org uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.org_member(org) AND EXISTS(SELECT 1 FROM public.memberships m JOIN public.membership_roles r ON r.membership_id=m.id WHERE m.organization_id=org AND m.user_id=auth.uid() AND m.status='active' AND r.role='admin') $$;
REVOKE ALL ON FUNCTION public.is_superadmin(),public.org_member(uuid),public.org_admin(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.is_superadmin(),public.org_member(uuid),public.org_admin(uuid) TO authenticated,service_role;
CREATE POLICY own_profile_read ON public.profiles FOR SELECT TO authenticated USING(id=auth.uid() OR public.is_superadmin());
CREATE POLICY own_profile_update ON public.profiles FOR UPDATE TO authenticated USING(id=auth.uid()) WITH CHECK(id=auth.uid());
CREATE POLICY tenant_org_read ON public.organizations FOR SELECT TO authenticated USING(public.org_member(id) OR public.is_superadmin());
CREATE POLICY tenant_subscription_read ON public.subscriptions FOR SELECT TO authenticated USING(public.org_admin(organization_id) OR public.is_superadmin());
CREATE POLICY tenant_membership_read ON public.memberships FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.org_admin(organization_id) OR public.is_superadmin());
CREATE POLICY tenant_roles_read ON public.membership_roles FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.memberships m WHERE m.id=membership_id AND (m.user_id=auth.uid() OR public.org_admin(m.organization_id) OR public.is_superadmin())));
CREATE POLICY tenant_invitation_read ON public.invitations FOR SELECT TO authenticated USING(public.org_admin(organization_id) OR public.is_superadmin());
CREATE POLICY tenant_audit_read ON public.audit_logs FOR SELECT TO authenticated USING(public.org_admin(organization_id) OR public.is_superadmin());
CREATE FUNCTION public.touch_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_touch BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER organizations_touch BEFORE UPDATE ON public.organizations FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER subscriptions_touch BEFORE UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER memberships_touch BEFORE UPDATE ON public.memberships FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE TRIGGER invitations_touch BEFORE UPDATE ON public.invitations FOR EACH ROW EXECUTE FUNCTION public.touch_updated_at();
CREATE FUNCTION public.create_auth_profile() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO public.profiles(id) VALUES(NEW.id) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.create_auth_profile() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER frankkia_profile_created AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.create_auth_profile();
INSERT INTO public.profiles(id) SELECT id FROM auth.users ON CONFLICT DO NOTHING;
CREATE FUNCTION public.assert_capacity(org uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE capacity integer; occupied integer; BEGIN PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE; SELECT p.broker_limit INTO capacity FROM public.subscriptions s JOIN public.plans p ON p.id=s.plan_id WHERE s.organization_id=org; SELECT (SELECT count(*) FROM public.memberships m JOIN public.membership_roles r ON r.membership_id=m.id WHERE m.organization_id=org AND m.status='active' AND r.role='broker') + (SELECT count(*) FROM public.invitations i WHERE i.organization_id=org AND i.status='pending' AND i.expires_at>now() AND 'broker'=ANY(i.roles)) INTO occupied; IF capacity IS NULL OR occupied>capacity THEN RAISE EXCEPTION 'Capacidade de corretores excedida.'; END IF; END $$;
CREATE FUNCTION public.check_tenant_invariants() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; active_admins integer; lost_admin boolean:=false; BEGIN
 IF TG_TABLE_NAME='membership_roles' THEN SELECT organization_id INTO org FROM public.memberships WHERE id=coalesce(NEW.membership_id,OLD.membership_id); lost_admin:=TG_OP='DELETE' AND OLD.role='admin';
 ELSIF TG_TABLE_NAME='memberships' THEN org:=coalesce(NEW.organization_id,OLD.organization_id); IF TG_OP='UPDATE' AND (NEW.organization_id<>OLD.organization_id OR NEW.user_id<>OLD.user_id) THEN RAISE EXCEPTION 'Vínculo imutável.'; END IF; lost_admin:=(TG_OP='DELETE' OR (OLD.status='active' AND NEW.status<>'active')) AND EXISTS(SELECT 1 FROM public.membership_roles WHERE membership_id=OLD.id AND role='admin');
 ELSE org:=coalesce(NEW.organization_id,OLD.organization_id); END IF;
 PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE;
 IF lost_admin THEN SELECT count(*) INTO active_admins FROM public.memberships m JOIN public.membership_roles r ON r.membership_id=m.id WHERE m.organization_id=org AND m.status='active' AND r.role='admin'; IF active_admins=0 THEN RAISE EXCEPTION 'A imobiliária precisa de um administrador ativo.'; END IF; END IF;
 PERFORM public.assert_capacity(org); RETURN NULL; END $$;
REVOKE ALL ON FUNCTION public.assert_capacity(uuid),public.check_tenant_invariants(),public.touch_updated_at() FROM PUBLIC,anon,authenticated;
CREATE CONSTRAINT TRIGGER memberships_invariants AFTER INSERT OR UPDATE OR DELETE ON public.memberships DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_tenant_invariants();
CREATE CONSTRAINT TRIGGER roles_invariants AFTER INSERT OR UPDATE OR DELETE ON public.membership_roles DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_tenant_invariants();
CREATE CONSTRAINT TRIGGER invites_invariants AFTER INSERT OR UPDATE OR DELETE ON public.invitations DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_tenant_invariants();
CREATE CONSTRAINT TRIGGER subscription_invariants AFTER INSERT OR UPDATE ON public.subscriptions DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_tenant_invariants();
CREATE FUNCTION public.create_organization(org_name text, catalog_plan text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN IF NOT public.is_superadmin() THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; INSERT INTO public.organizations(name) VALUES(trim(org_name)) RETURNING id INTO org; INSERT INTO public.subscriptions(organization_id,plan_id) VALUES(org,catalog_plan); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id) VALUES(org,auth.uid(),'organization.created',org); RETURN org; END $$;
CREATE FUNCTION public.reserve_invitation(org uuid, invited_email text, requested_roles text[], hashed_token text, expires timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invitation uuid; BEGIN PERFORM 1 FROM public.organizations WHERE id=org AND status='active' FOR UPDATE; IF NOT FOUND OR NOT (public.is_superadmin() OR public.org_admin(org)) THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; IF expires<=now() OR expires>now()+interval '7 days' THEN RAISE EXCEPTION 'Prazo de convite inválido.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE organization_id=org AND status='active') THEN RAISE EXCEPTION 'Assinatura indisponível.'; END IF; IF EXISTS(SELECT 1 FROM public.invitations WHERE organization_id=org AND email=lower(trim(invited_email)) AND status='pending' AND expires_at>now()) THEN RAISE EXCEPTION 'Já existe convite pendente para este e-mail.'; END IF; IF EXISTS(SELECT 1 FROM public.memberships m JOIN auth.users u ON u.id=m.user_id WHERE m.organization_id=org AND lower(u.email)=lower(trim(invited_email)) AND m.status='active') THEN RAISE EXCEPTION 'Usuário já possui acesso ativo.'; END IF; INSERT INTO public.invitations(organization_id,email,roles,token_hash,expires_at,created_by) VALUES(org,lower(trim(invited_email)),requested_roles,hashed_token,expires,auth.uid()) RETURNING id INTO invitation; PERFORM public.assert_capacity(org); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id) VALUES(org,auth.uid(),'invitation.reserved',invitation); RETURN invitation; END $$;
CREATE FUNCTION public.revoke_invitation(invitation_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE org uuid; BEGIN SELECT organization_id INTO org FROM public.invitations WHERE id=invitation_id; PERFORM 1 FROM public.organizations WHERE id=org FOR UPDATE; IF NOT (public.is_superadmin() OR public.org_admin(org)) THEN RAISE EXCEPTION 'Acesso não autorizado.'; END IF; UPDATE public.invitations SET status='revoked',revoked_at=now() WHERE id=invitation_id AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION 'Convite indisponível.'; END IF; INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id) VALUES(org,auth.uid(),'invitation.revoked',invitation_id); END $$;
CREATE FUNCTION public.accept_invitation(hashed_token text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE invite public.invitations; member uuid; verified_email text; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Entre para aceitar o convite.'; END IF; SELECT * INTO invite FROM public.invitations WHERE token_hash=hashed_token; IF NOT FOUND THEN RAISE EXCEPTION 'Convite inválido ou expirado.'; END IF; PERFORM 1 FROM public.organizations WHERE id=invite.organization_id AND status='active' FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Imobiliária indisponível.'; END IF; SELECT * INTO invite FROM public.invitations WHERE id=invite.id FOR UPDATE; SELECT lower(email) INTO verified_email FROM auth.users WHERE id=auth.uid() AND email_confirmed_at IS NOT NULL; IF invite.status<>'pending' OR invite.expires_at<=now() OR invite.email IS DISTINCT FROM verified_email THEN RAISE EXCEPTION 'Convite inválido, expirado ou destinado a outro e-mail.'; END IF; IF NOT EXISTS(SELECT 1 FROM public.subscriptions WHERE organization_id=invite.organization_id AND status='active') THEN RAISE EXCEPTION 'Assinatura indisponível.'; END IF; UPDATE public.invitations SET status='accepted',accepted_by=auth.uid(),accepted_at=now() WHERE id=invite.id; INSERT INTO public.memberships(organization_id,user_id,status) VALUES(invite.organization_id,auth.uid(),'active') ON CONFLICT(organization_id,user_id) DO UPDATE SET status='active' RETURNING id INTO member; INSERT INTO public.membership_roles(membership_id,role) SELECT member,unnest(invite.roles) ON CONFLICT DO NOTHING; PERFORM public.assert_capacity(invite.organization_id); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id) VALUES(invite.organization_id,auth.uid(),'invitation.accepted',invite.id); RETURN invite.organization_id; END $$;
CREATE FUNCTION public.manage_membership(member_id uuid, desired_status text, desired_roles text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE member public.memberships; BEGIN SELECT * INTO member FROM public.memberships WHERE id=member_id; PERFORM 1 FROM public.organizations WHERE id=member.organization_id FOR UPDATE; IF member.user_id=auth.uid() OR NOT (public.is_superadmin() OR public.org_admin(member.organization_id)) THEN RAISE EXCEPTION 'Acesso não autorizado; seu próprio vínculo não pode ser alterado.'; END IF; IF cardinality(desired_roles)=0 OR desired_roles IS NULL OR NOT desired_roles <@ ARRAY['admin','broker']::text[] THEN RAISE EXCEPTION 'Papéis inválidos.'; END IF; UPDATE public.memberships SET status=desired_status WHERE id=member_id; DELETE FROM public.membership_roles WHERE membership_id=member_id AND NOT role=ANY(desired_roles); INSERT INTO public.membership_roles(membership_id,role) SELECT member_id,unnest(desired_roles) ON CONFLICT DO NOTHING; PERFORM public.assert_capacity(member.organization_id); INSERT INTO public.audit_logs(organization_id,actor_id,action,target_id,details) VALUES(member.organization_id,auth.uid(),'membership.updated',member_id,jsonb_build_object('status',desired_status,'roles',desired_roles)); END $$;
REVOKE ALL ON FUNCTION public.create_organization(text,text),public.reserve_invitation(uuid,text,text[],text,timestamptz),public.revoke_invitation(uuid),public.accept_invitation(text),public.manage_membership(uuid,text,text[]) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.create_organization(text,text),public.reserve_invitation(uuid,text,text[],text,timestamptz),public.revoke_invitation(uuid),public.accept_invitation(text),public.manage_membership(uuid,text,text[]) TO authenticated;
COMMENT ON TABLE public.plans IS 'Catalog only; no payment collection. Initial rows backfill the new catalog.';
COMMENT ON TABLE public.user_roles IS 'Superadmin bootstrap is privileged and out-of-band; never derive from profile metadata.';